    //     double elapsed_time = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1e9;
    //     rtime += elapsed_time; /**/ if (echeck == DARENA_OVERFLOW) test_cleanup(&div_arena, ret_arr, ret_cnt, log_arr, log_cnt); 
    //     int8_t match = __BIGINT_INTERNAL_COMP__(&ret, &div_cases[i].exp_quot);
    //     if (!match) passed_tests++;
    //     else {
    //         fprintf(log_arr[curr_log],
